import{z as E,x as g,o as t,c as d,q as l,j as o,D as a,d as n,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"slime 轻量 RL 框架","description":"","frontmatter":{"title":"slime 轻量 RL 框架","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/slime-rl.md","filePath":"llm/slime-rl.md","lastUpdated":1791063341000}'),m={name:"llm/slime-rl.md"};function p(A,e,L,c,h,B){const r=g("Mermaid");return t(),d("div",null,[e[2]||(e[2]=l('<h1 id="slime-轻量-rl-框架" tabindex="-1">slime 轻量 RL 框架 <a class="header-anchor" href="#slime-轻量-rl-框架" aria-label="Permalink to &quot;slime 轻量 RL 框架&quot;">​</a></h1><div class="epigraph"><p>我们故意只接一条推理后端，好把 SGLang 的路由、缓存、分离式服务和权重同步直接用在 RL 上，而不是先抽成各引擎的最小公约数。</p><footer>—— slime Team，slime: An SGLang-Native Post-Training Framework for RL Scaling，LMSYS Blog，2025-07-09</footer></div><p>多数开源 RL 框架把「多后端」写成优点：同一套 PPO 既能打 vLLM 也能打 SGLang。抽象层会把每个引擎最强的特性削平。清华 THUDM 的 <strong>slime</strong>（仓库 <code>THUDM/slime</code>，文档 thudm.github.io/slime）走相反的意见：<strong>训练只认 Megatron</strong>，<strong>rollout 只认 SGLang</strong>，中间用 Data Buffer 和 Ray 把采样、奖励、更新串成一条路径。2025 年 7 月 9 日 LMSYS 博客把它定位为 SGLang 原生的 RL scaling 框架；后续 README 写它支撑了 GLM-4.5 到 GLM-4.7 乃至更新代际的完整训练环。本篇钉「轻量」指编排层薄、不是指模型小；钉自定义生成钩子如何让 agent 工作流不必另起一套训练核。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RL 后训练相对预训练多了一条必须在线采样的边。若训练核是 Megatron，推理核却是另一套检查点格式，每步都要转换权重、对齐精度、再启动服务，失败模式是静默的数值漂移。多后端框架为了接口统一，往往不能把 SGLang 的 radix 前缀缓存、router、PD 分离直接暴露给 RL 循环。slime 认为：实验室一旦选定 Megatron 预训练，后训练就应该继续用同一套并行参数，部署再继续用同一套 SGLang；转换步骤越少，越能把预训练的 MFU 经验迁到 RL。</p><p><span class="marginnote">术语翻译：radix 前缀缓存是 SGLang 的看家本领——把请求共享的前缀（同一段系统提示、同一批文档）存成树，后续请求直接复用 KV，不重算。RL 里同一个提示要采样几十条回答，前缀只算一次，吞吐能差好几倍。多后端抽象层削平的正是这类特性。</span></p><p>第二问是数据生成的多样性。数学验证器、搜索、沙箱、多 agent 都想插在采样里，但不想 fork 训练循环。若每个 agent 框架都自带一份 PPO，Megatron 侧的并行与优化器 bug 会分叉。slime 把 agent 写成「自定义数据生成」，训练 / rollout / buffer 仍是同一条管线。</p><h3 id="轻量不等于功能少" tabindex="-1">轻量不等于功能少 <a class="header-anchor" href="#轻量不等于功能少" aria-label="Permalink to &quot;轻量不等于功能少&quot;">​</a></h3><p>代码量小来自<strong>拒绝多后端抽象</strong>。Megatron 参数原样透传，SGLang 参数用 <code>--sglang-</code> 前缀暴露。新的上游优化（一种并行、一种 kernel）不必在 slime 里再包一层。这与 <a href="/llm/openrlhf">OpenRLHF</a> 的 HF 友好、<a href="/llm/trl-framework">TRL</a> 的 Trainer 目录是不同的薄：后两者薄在模型类，slime 薄在编排，厚在两条上游引擎。读「轻量」时不要理解成只能训 7B。</p><p><span class="marginnote">博客强调 colocated 或 decoupled、同步或异步都能配。默认并不是 AReaL 那种完全解耦；要完全异步应看仓库 <code>examples/fully_async</code> 与 staleness 配置，不能从框架名推断时序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三件套：Ray 管 GPU 与异步执行；Megatron 做带 TP/PP/EP/CP 的更新，并报告训练 MFU；SGLang 加 sgl-router 做高吞吐生成。Data Buffer 保存提示、采样 token、对数概率、奖励与分组元数据，使 GRPO / PPO / GSPO / REINFORCE++ 等算法读同一份样本契约。权重同步有多条路径：同机房可用 NCCL 全量广播；分离集群可用文件系统上的 delta（按字节差分）。第一步往往先 seed CPU 快照，再在后续 step 只推变化。</p><p>自定义点用 import path 注入，而不是改核心：</p><ul><li><code>--custom-generate-function-path</code>：单条样本上的多轮工具、RAG、沙箱，仍复用默认 <code>sglang_rollout</code> 外循环。<code>examples/search-r1</code> 是这条路。</li><li><code>--custom-rm-path</code>：验证器、单测、外部奖励服务。</li><li><code>--rollout-function-path</code>：整段编排都要换时才用，例如 <code>examples/multi_agent</code>。</li><li><code>--rollout-data-postprocess-path</code>：补 <a href="/llm/multiturn-loss-mask">loss mask</a> 或把 agent 输出收成训练张量。</li></ul><p>调试长工具调用可用 <code>slime.utils.trace_utils</code>。<code>--debug-train-only</code> 可关掉采样，只练 Megatron 侧。</p>',15)),(t(),o(i,null,{default:a(()=>[s(r,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20LR%0A%20%20MEG%5B%22Megatron%20%E8%AE%AD%E7%BB%83%22%5D%20--%3E%7C%22%E6%9D%83%E9%87%8D%E5%90%8C%E6%AD%A5%22%7C%20SGL%5B%22SGLang%20%2B%20router%22%5D%0A%20%20SGL%20--%3E%20GEN%5B%22%E8%87%AA%E5%AE%9A%E4%B9%89%20generate%20%2F%20%E7%8E%AF%E5%A2%83%22%5D%0A%20%20GEN%20--%3E%20RM%5B%22%E8%87%AA%E5%AE%9A%E4%B9%89%20RM%20%2F%20%E9%AA%8C%E8%AF%81%E5%99%A8%22%5D%0A%20%20RM%20--%3E%20BUF%5B%22Data%20Buffer%22%5D%0A%20%20BUF%20--%3E%20MEG%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l('<h3 id="原生透传的代价是绑定" tabindex="-1">原生透传的代价是绑定 <a class="header-anchor" href="#原生透传的代价是绑定" aria-label="Permalink to &quot;原生透传的代价是绑定&quot;">​</a></h3><p>Megatron 参数直通意味着你必须会 Megatron 启动惯例；SGLang 前缀意味着 rollout 行为跟该版 SGLang 绑定。换 vLLM 不是改一个 flag。这是显式的产品选择：GLM 系从 Megatron 预训练走到 SGLang 服务，中间用 slime，避免「预训练一个格式、RL 一个格式、上线再转一次」。用 HuggingFace 权重为主、没有 Megatron 检查点的团队，<a href="/llm/trl-framework">TRL</a> 或 OpenRLHF 更贴。</p><p><span class="marginnote">文档列举的模型家族包括 GLM-4.x、Qwen3、DeepSeek V3/R1、Llama 3 等，是「引擎能跑」的覆盖，不是每张卡都有官方吞吐表。引用 GLM 代际时跟 README 当时列表走，不要把未写入的版本算进框架论文。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Data Buffer 让训练核不必知道工具协议。生成函数只要最终交出 token 与 mask；奖励函数交出标量或逐步分；Megatron 只看张量。Agent 工作流因此不会逼你把 <a href="/llm/openhands">OpenHands</a> 嵌进 C++ 运行时。代价是：若自定义 generate 在 Python 里串行等工具，GPU decode 仍会空转——异步与分离式服务要自己打开，框架只提供钩子。LMSYS 文把「可维护」写成与 SGLang、Megatron 上游同步的能力：上游修一个 serving bug，RL 循环马上能用，不必等中间抽象层适配。</p><p>权重 delta 同步假设两次更新之间参数变化稀疏或可按桶编码。全量 NCCL 在单数据中心更简单、更易正确；跨机房文件系统 delta 省带宽，但要处理失败重试与版本号。slime 把 <code>weight_version</code> 设到 engine 上，避免训练步与生成步对不上。这与 AReaL 的策略版本号是同一类簿记，实现不共享。</p>',6)),(t(),o(i,null,{default:a(()=>[s(r,{id:"mermaid-81",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPD%5B%22Megatron%20%E6%9B%B4%E6%96%B0%E5%AE%8C%E4%B8%80%E6%AD%A5%22%5D%20--%3E%20VER%5B%22weight_version%20%E5%8A%A0%E4%B8%80%22%5D%0A%20%20VER%20--%3E%20Q%7B%22%E8%AE%AD%E7%BB%83%E4%B8%8E%E6%8E%A8%E7%90%86%E5%9C%A8%E5%90%8C%E4%B8%80%E6%9C%BA%E6%88%BF%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20NCCL%5B%22NCCL%20%E5%85%A8%E9%87%8F%E5%B9%BF%E6%92%AD%EF%BC%8C%E7%AE%80%E5%8D%95%E5%8F%AF%E9%9D%A0%22%5D%0A%20%20Q%20--%3E%7C%22%E8%B7%A8%E6%9C%BA%E6%88%BF%22%7C%20DELTA%5B%22%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%E6%8C%89%E5%AD%97%E8%8A%82%E5%B7%AE%E5%88%86%E6%8E%A8%20delta%22%5D%0A%20%20NCCL%20--%3E%20LOAD%5B%22SGLang%20%E5%8A%A0%E8%BD%BD%E6%96%B0%E7%89%88%E6%9D%83%E9%87%8D%22%5D%0A%20%20DELTA%20--%3E%20RETRY%5B%22%E5%A4%84%E7%90%86%E9%87%8D%E8%AF%95%E4%B8%8E%E7%89%88%E6%9C%AC%E6%A0%B8%E5%AF%B9%22%5D%20--%3E%20LOAD%0A%20%20LOAD%20--%3E%20GEN%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%20rollout%20%E7%94%A8%E6%96%B0%E7%AD%96%E7%95%A5%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=l('<p><span class="marginnote">数字实例：8B 模型按 bf16 存全量约 16 GB；RL 一步往往只动一小部分参数，差分后的 delta 可能只有几百 MB。单机房 16 GB 走 NCCL 秒级完成；跨机房每步传 16 GB，一千步就是 16 TB 的流量账——这是 delta 同步存在的理由。</span></p><h3 id="和「多后端框架」如何并存" tabindex="-1">和「多后端框架」如何并存 <a class="header-anchor" href="#和「多后端框架」如何并存" aria-label="Permalink to &quot;和「多后端框架」如何并存&quot;">​</a></h3><p>verl、<a href="/llm/nemo-rl">NeMo-RL</a> 把多引擎当一等需求，适合要扫 vLLM / SGLang / TRT 的平台组。slime 适合已经押 SGLang 服务、Megatron 训练的组织。Molt 等后续工作在文献里把 slime 归到「Megatron-Core 承诺、编排薄」的一端。没有绝对更快：SGLang 的前缀缓存对多轮共享前缀极有利，对无共享的短提示优势会收窄。选框架先写清检查点与推理栈，再谈行数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把「battle-tested by GLM」理解成任意任务的质量保证；那是训练环在真实发布里跑通。不要在未提供 mask 的自定义 generate 里把工具 JSON 送进策略损失。异步长尾例子与默认同步 GRPO 的超参不能混用。CPU 契约测试覆盖的是 hook 的导入路径，不是你的沙箱是否在集群里可复现。</p><p>若必须接非 SGLang 引擎，slime 不是正确工具。若必须在消费级单卡上扫 DPO，回到 TRL。slime 的意见是：规模化 RL 时，少一层胶水比多一个后端开关更重要。</p><p><span class="marginnote">出处：LMSYS <em>slime: An SGLang-Native Post-Training Framework for RL Scaling</em>（2025-07-09）；仓库 <a href="https://github.com/THUDM/slime%E3%80%82Megatron-LM" target="_blank" rel="noreferrer">https://github.com/THUDM/slime。Megatron-LM</a> 见 Shoeybi 等；SGLang 见 Zheng 等。Agent 向设计另有团队 Notion 文，引用时与博客分开，不要把未评审笔记写成 EuroSys 论文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>slime 用薄编排连接 Megatron 训练与 SGLang rollout，Data Buffer 承接样本与奖励。</li><li>自定义 generate / RM 让 agent 工作流进同一条训练核，而不是另起 PPO 实现。</li><li>只接一条推理后端是为了用满 SGLang，不是功能残缺。</li><li>出处：LMSYS 2025-07-09 博客；<a href="https://github.com/THUDM/slime%E3%80%82" target="_blank" rel="noreferrer">https://github.com/THUDM/slime。</a></li></ul>',9))])}const D=E(m,[["render",p]]);export{f as __pageData,D as default};
